"""Inventory: stock count records."""

TABLE = "stock_count"
FIELDS = ('sku', 'warehouse', 'counted')


def ensure_table(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS stock_count (id INTEGER PRIMARY KEY, sku TEXT, warehouse TEXT, counted TEXT)")


def create(conn, sku, warehouse, counted):
    ensure_table(conn)
    cur = conn.execute("INSERT INTO stock_count(sku, warehouse, counted) VALUES (?,?,?)", (sku, warehouse, counted,))
    conn.commit()
    return cur.lastrowid


def get(conn, row_id):
    ensure_table(conn)
    return conn.execute("SELECT * FROM stock_count WHERE id=?", (row_id,)).fetchone()


def list_all(conn, limit=100):
    ensure_table(conn)
